import { homedir } from "node:os";

const STATE_PATH = `${homedir()}/.local/share/opencode/phase0-state.json`;
const DB_PATH = `${homedir()}/.local/share/opencode/opencode.db`;
const MEMORY_SESSIONS = `${homedir()}/.local/share/opencode/memory/sessions`;

const PHASE0_TOOLS = new Set(["memory_search", "skill", "read", "phase0_complete"]);
const CHECKPOINT_MIN_MSGS = 30;
const CHECKPOINT_ALLOWED = new Set(["task", "memory_search", "read", "skill", "checkpoint_done"]);

