          // сбросить флаг
          return "✅ Checkpoint Gate снят.";
        }
      });
    });

    // === События ===
    ctx.event.subscribe((event) => {
      if (event.type === "session.created") {
        state.cycle1Completed = false;
      }
    });
  },
